INSERT INTO products (product_id, category_id, brand_id, supplier_id, name, short_description, description, price, stock_quantity, source_store, source_url, is_active)
VALUES
    (101, 103, 101, 101, 'Khamrah', 'An opulent, award-winning oriental gourmand blending warm spices, sweet dates, and creamy praline with smoky amber.', 'Khamrah by Lattafa Perfumes is a luxurious unisex oriental-spicy fragrance that combines precious spices, the sweetness of praline and date fruit, and the richness of vanilla and amberwood. Inspired by traditional Arabian hospitality, it opens with a radiant burst of cinnamon and nutmeg before melting into a heart of dates and praline.', 9500, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (102, 101, 101, 101, 'Asad', 'A powerhouse masculine fragrance characterized by rich black pepper, smoky tobacco, roasted coffee, and smooth vanilla.', 'Asad by Lattafa Perfumes is an iconic amber masculine fragrance crafted for the commanding gentleman. Opening with an arresting accord of black pepper and dark tobacco sweetened with pineapple, it evolves into an addictive roasted coffee and iris core supported by opulent amber and warm vanilla.', 7800, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (103, 102, 101, 101, 'Yara', 'The viral pink sensation: fluffy vanilla, sweet marshmallow fluff, heliotrope, and delicate tropical fruits.', 'Yara by Lattafa is an enchanting, playful feminine fragrance renowned worldwide for its creamy strawberry-milkshake and marshmallow character. It wraps the wearer in an aura of velvety heliotrope, luscious tropical fruits, comforting Madagascar vanilla, and warm sandalwood.', 7200, 75, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (104, 102, 101, 101, 'Yara Candy', 'A sparkling, mouthwatering confection of fizzy strawberry candy, juicy blackcurrant, and spun vanilla sugar.', 'The newest iteration of the beloved Yara line, Yara Candy elevates sweet gourmand perfumery with bright, effervescent candied tangerine and sparkling strawberry fizz. Grounded in comforting vanilla syrup and amber, it delivers irresistible youthfulness and long-lasting charm.', 8500, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (105, 102, 101, 101, 'Eclaire', 'The ultimate dessert perfume: warm condensed milk, molten caramel, golden honey, and rich vanilla waffle pastry.', 'Eclaire by Lattafa is a luxurious culinary masterpiece. Designed for true gourmand devotees, it captures the scent of a Parisian pÃ¢tisserie with decadent caramel, warm condensed milk, honeyed pastry notes, and velvety vanilla bean that lingers gracefully for 12+ hours.', 11500, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (106, 102, 101, 101, 'Angham', 'An intoxicating melodic symphony of zesty ginger, elegant French lavender, nutty praline, and warm golden vanilla.', 'Angham by Lattafa translates to ''Melodies'' in Arabic. It offers a sophisticated balance of crisp citrus-spice, aromatic French lavender, and an irresistible creamy praline and bourbon vanilla foundation that exudes refined confidence.', 9800, 30, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (107, 103, 101, 101, 'Khamrah Dukhan', 'The dark, sultry smoky sister to Khamrah: intense frankincense smoke, caramelized dates, and smoky Cambodian agarwood.', 'Khamrah Dukhan explores the mystical, nocturnal side of the Khamrah heritage. Infusing sacred bakhur smoke and resinous frankincense with the iconic cinnamon-date praline accord, it creates an unforgettable presence suited for formal evenings.', 10800, 25, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (108, 103, 101, 101, 'Teriaq', 'Master perfumer Quentin Bisch''s creation: bitter almond, wild honey, tart rhubarb, and supple, buttery leather.', 'Teriaq by Lattafa is a groundbreaking artisanal creation formulated by master French perfumer Quentin Bisch. Uniting contrasting worlds, it melds tart rhubarb and apricot with sticky honey, velvety caramel, and a sensuous, high-fashion leather trail.', 13500, 20, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (109, 102, 101, 101, 'Badee Al Oud Noble Blush', 'A delicate yet opulent blush fantasy: sweet almond milk, whipped meringue, powdered rose petals, and creamy woods.', 'Badee Al Oud Noble Blush is the feminine crown jewel of the Badee Al Oud saga. Departing from heavy oud into ethereal lactonic luxury, it blends candied almonds, sweet rosewater milk, and whipped meringue over a silky sandalwood foundation.', 8900, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (110, 101, 101, 101, 'His Confession', 'A refined gentleman''s nocturnal elixir: warm cinnamon, powdery Tuscan iris, resinous benzoin, and noble cedar.', 'His Confession represents intimate elegance and magnetic charisma. Featuring velvety iris enveloped in fiery cinnamon, warm mandarin, and resinous amber, this fragrance commands respect and intrigue in every room.', 9200, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (111, 102, 101, 101, 'Victoria', 'A regal feminine bouquet: glistening red berries, dewy peony petals, velvety damask rose, and cashmere musk.', 'Victoria by Lattafa is a celebration of royal femininity. Bursting with succulent berries and sun-drenched peaches, it flows effortlessly into a lush floral bouquet of rose and peony, drying into an addictive cashmere musk veil.', 8000, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (112, 101, 101, 101, 'The Kingdom Men', 'A sovereign aromatic composition: icy mint, royal lavender, orange blossom, and a sensual tonka-vanilla base.', 'The Kingdom Men channels masculine majesty and timeless strength. Its crystalline opening of cooling mint and sage gives way to an aristocratic heart of lavender and orange blossom, anchored by seductive tonka and cedarwood.', 8400, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (113, 103, 101, 101, 'Liam Grey', 'The quintessential Parisian tea-and-fig masterpiece: creamy black fig, smoky black tea, cardamom, and sandalwood.', 'Liam Grey by Lattafa is celebrated globally for its impeccable recreation of the beloved Gris Charnel profile. Blending smoky black tea with velvety fig pulp, aromatic cardamom, and a luxurious sandalwood-vanilla foundation, it is universally adored by fragrance connoisseurs.', 8800, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (114, 101, 101, 101, 'Asad Zanzibar', 'An exotic oceanic adventure: black pepper, mineral sea spray, salted coconut water, and smoky incense.', 'Asad Zanzibar is a daring, modern evolution of the Asad legacy. Inspired by the spice island of Zanzibar, it contrasts cooling oceanic waves and salty coconut with sharp black pepper, powdery iris, and resinous incense.', 8200, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (115, 103, 101, 101, 'Atheeri', 'An ethereal oriental treasure: vibrant golden saffron, crimson Taif roses, earthy patchouli, and clean amber.', 'Atheeri captures the celestial grace of ancient Arabian palaces. A radiant pairing of saffron and fresh rose is deepened by earthy patchouli and sunlit amber, resulting in an aristocratic fragrance of remarkable longevity.', 9500, 30, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (116, 103, 102, 101, 'Art Of Universe', 'Cosmic prestige from the Pride collection: zesty blood orange, frankincense resin, aromatic herbs, and amber crystals.', 'Part of the prestigious Lattafa Pride collection, Art Of Universe is an artistic tribute to cosmic harmony. Crisp, energetic blood orange and elemi transition into spiritual frankincense and rich woods, presented in an exquisite sculpted flacon.', 11000, 25, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (117, 103, 102, 101, 'Art Of Nature II', 'An organic, botanic masterpiece: cooling mint, wild artemisia, earthy forest oakmoss, and soft leather.', 'Art Of Nature II from Lattafa Pride reconnects the senses with untouched wilderness. Featuring crisp mountain air accords, velvety green moss, powdery orris, and rich leather, it is an evocative unisex creation for modern explorers.', 11200, 25, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (118, 102, 101, 101, 'Yara Tous', 'The vibrant yellow Yara: sun-drenched Alphonso mango, creamy coconut milk, and exotic white florals.', 'Yara Tous is the ultimate tropical summer indulgence. Bursting with succulent mango, passionfruit, and creamy coconut milk, it carries the spirit of a luxury island getaway in a stunning golden flacon.', 7500, 65, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (119, 102, 101, 101, 'Yara Moi', 'The elegant white Yara: velvety ripe peaches, melted golden caramel, and clean white florals.', 'Yara Moi (known as White Yara) provides a sophisticated, mature dimension to the collection. Centered around sweet peaches and decadent caramel, it is balanced with patchouli and sandalwood for remarkable evening longevity.', 7400, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (120, 101, 101, 101, 'Asad Bourbon', 'A boozy, intoxicating masculine warm fragrance: aged bourbon whiskey, toasted tonka, and dark cocoa.', 'Asad Bourbon introduces an opulent cask-aged dimension to the Asad dynasty. Opening with aromatic cardamom and rich bourbon, it transitions through roasted cocoa and tonka into an enduring oak-amber drydown.', 8600, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (121, 103, 101, 101, 'Khamrah Qahwa', 'The acclaimed coffee flanker: dark roasted Arabic qahwa, green cardamom, cinnamon, and pralines.', 'Khamrah Qahwa elevates the legendary Khamrah DNA by introducing an authentic, dark roasted Arabic coffee accord. Accented by fresh cardamom and ginger, this fragrance has become an instant winter icon.', 10500, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (122, 103, 101, 101, 'Badee Al Oud Oud For Glory', 'The dark legend: noble saffron, nutmeg, earthy patchouli, and deep, smoky natural agarwood.', 'Badee Al Oud Oud For Glory is widely hailed as one of the finest oud creations in modern perfumery. Featuring rich saffron, dark patchouli, and smoky agarwood in a matte black and gold bottle, it embodies absolute power and prestige.', 8200, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (123, 103, 101, 101, 'Badee Al Oud Sublime', 'The vibrant crimson edition: juicy red apples, sweet litchi, dark plum, and earthy green moss.', 'Sublime by Badee Al Oud presents an addictive fruity-floral profile. Crisp green and red apples combine with decadent plum and rose before resting on a bed of velvety moss and patchouli.', 8200, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (124, 103, 101, 101, 'Badee Al Oud Honor & Glory', 'The pristine white and gold edition: caramelized pineapple crÃ¨me brÃ»lÃ©e, warm spices, and creamy vanilla.', 'Honor & Glory is an extraordinary gourmand achievement. Opening with caramelized pineapple crÃ¨me brÃ»lÃ©e dusted with cinnamon, it unfolds into warm benzoin and creamy sandalwood for a deliciously opulent sillage.', 8500, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (125, 103, 101, 101, 'Badee Al Oud Amethyst', 'The royal purple jewel: dual Turkish and Bulgarian roses enveloped in dark oud, sweet amber, and bourbon vanilla.', 'Badee Al Oud Amethyst is an intoxicating rose-oud spectacle. Featuring dual distillations of Bulgarian and Turkish roses warmed with pink pepper, amber, and Cambodian oud, it radiates aristocratic elegance.', 8200, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (126, 103, 102, 101, 'Nebras', 'Sensational cocoa and vanilla treat: frosted red berries, rich cacao pod, warm melted sugar, and tonka.', 'Nebras from Lattafa Pride is celebrated as the pinnacle of cozy gourmands. Opening with sparkling red berries and mandarin, it wraps the senses in warm hot-cocoa, powdery rose, and buttery Madagascar vanilla.', 10500, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (127, 103, 102, 101, 'Vintage Radio', 'Nostalgic artisan perfection: luscious dark plum, mystical palo santo wood, lavender, and sandalwood.', 'Vintage Radio from Lattafa Pride is an artistic triumphs in modern niche perfumery. Harmonizing sweet dark plum with sacred Palo Santo wood and soothing lavender, it offers unparalleled depth and sophistication.', 11000, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (128, 102, 102, 101, 'Affection', 'Creamy pistachio gelato perfection: roasted hazelnuts, creamy milk froth, sweet vanilla, and delicate jasmine.', 'Affection by Lattafa Pride translates the craveable pleasure of Italian pistachio gelato into haute perfumery. Creamy, nutty, and sweet with floral nuances, it leaves an irresistible, comforting cloud everywhere you go.', 10500, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (129, 103, 102, 101, 'Eternal Oud', 'Regal amber flacon under a glass cloche: syrupy dark plum, powdery orchid, benzoin tears, and royal amber.', 'Presented under an ornate presentation dome, Eternal Oud is a majestic amber fragrance. It marries sweet plum with powdery floral notes and a hypnotic resinous base of benzoin, labdanum, and precious oud.', 11500, 30, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (130, 101, 102, 101, 'Art of Arabia I', 'A tribute to Arabian heritage: crisp bergamot, iced black tea, zesty ginger, and mineral ambroxan.', 'Art of Arabia I honors the ancient desert trade routes. Uplifting mint and bergamot sparkle over an aromatic core of black tea and ginger, settling into a long-lasting cedar-ambroxan trail.', 10800, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (131, 103, 102, 101, 'Masa', 'Unique diamond flacon: tart green mango, precious golden saffron, apricot-scented osmanthus, and soft suede.', 'Masa represents absolute luxury. Pairing tropical green mango and radiant saffron with mineral accords and velvety suede, this niche masterpiece is reminiscent of bespoke artisan perfumery.', 12500, 25, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (132, 103, 102, 101, 'Hala', 'Warm woody spirituality: crushed nutmeg, cracked black pepper, golden amber, and holy frankincense.', 'Hala from Lattafa Pride is a deeply meditative fragrance. With its minimalist, architectural composition of pepper, nutmeg, resinous labdanum, and church incense, it provides an intimate, grounding scent bubble.', 10200, 30, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (133, 103, 102, 101, 'Winners Trophy Gold', 'The golden victory: spiced plum, blooming white jasmine, earthy patchouli, and bourbon vanilla.', 'Winners Trophy Gold celebrates triumphal milestones with rich plum, spicy pink pepper, and creamy patchouli-vanilla in an iconic golden trophy bottle.', 11500, 25, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (134, 103, 102, 101, 'Shaheen Gold', 'The falcon''s flight: sparkling sweet pineapple, luscious fig, aromatic lavender, and smooth tonka.', 'Shaheen Gold is inspired by the regal Arabian falcon. Sweet golden pineapple and green fig marry with calming lavender and tonka bean, delivering effortless elegance and broad appeal.', 11000, 30, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (135, 101, 102, 101, 'Al Qiam Silver', 'The pinnacle of modern freshness: sparkling grapefruit, spicy ginger root, and mineral ambroxan.', 'Al Qiam Silver delivers an invigorating blast of effervescent grapefruit and spicy ginger atop smooth sandalwood and ambroxan, making it the perfect signature scent for all seasons.', 10500, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (136, 101, 101, 101, 'Fakhar Black', 'The undefeated blue-fragrance king: crisp green apple, aromatic sage, lavender, and amberwood.', 'Fakhar Black (often hailed as the silver-framed black crest bottle) is an irresistible compliment magnet. Blending green apple, ginger, and aromatic clary sage with rich amberwood, it defines everyday excellence.', 6800, 80, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (137, 102, 101, 101, 'Fakhar Rose', 'Luminous floral white-gold crest: sweet pomegranate, opulent tuberose, gardenia, and vanilla.', 'Fakhar Rose is a grand feminine floral bouquet. Sparkling pomegranate and aldehydes open the path for intoxicating white blossomsâ€”tuberose, gardenia, and jasmineâ€”resting on a bed of sweet vanilla.', 6800, 70, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (138, 103, 101, 101, 'Qaed Al Fursan', 'The mouthwatering sweet pineapple bomb: juicy grilled pineapple, saffron threads, fir balsam, and cedar.', 'Qaed Al Fursan (Black Horse) is renowned for its hyper-realistic, mouthwatering sweet pineapple opening. Supported by precious saffron, fir balsam, and clean woods, it is universally loved for its uplifting energy.', 5800, 85, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (139, 103, 101, 101, 'Qaed Al Fursan Unlimited', 'Creamy white coconut resort: rich coconut cream, tropical frangipani blossoms, and sweet vanilla musk.', 'Qaed Al Fursan Unlimited (White Horse) is a blissful lactonic escape. Featuring luscious coconut cream and tropical frangipani warmed by golden vanilla, it is clean, summery, and deeply comforting.', 6200, 65, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (140, 103, 101, 101, 'Ameer Al Oudh Intense Oud', 'Cozy fireside warmth: toasted marshmallows, caramelized sugar, sweet vanilla, and smoky oak wood.', 'Ameer Al Oudh Intense Oud is the ultimate winter comfort fragrance. Reminiscent of marshmallows toasting over sweet aromatic wood fires, it combines caramelized sugar, bourbon vanilla, and smooth agarwood.', 6400, 70, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (141, 103, 101, 101, 'Raghba', 'The classic oriental sweet legend: dark caramelized sugar, incense smoke, rich vanilla, and sandalwood.', 'Raghba is one of Lattafa''s foundational heritage creations. A sweet, smoky oriental fragrance, it marries raw sugar, fragrant vanilla, and aromatic bakhur incense over rich sandalwood.', 5400, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (142, 101, 101, 101, 'Raghba Wood Intense', 'Dark smoky timber: charred cedar, dark caramel, licorice root, burning guaiac wood, and amber.', 'Raghba Wood Intense amplifies the dark, smoky wood character of the original. Heavy notes of guaiac wood, charred cedar, and resinous incense are enriched with dark caramel and licorice.', 5800, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (143, 103, 101, 101, 'Maahir', 'The golden stallion: sparkling peach bellini, red berries, royal peony blossoms, and smooth vanilla.', 'Maahir (Original Gold Horse) is an imposing fragrance in an ornate horse-head flacon. Combining sparkling peach bellini with rich floral peonies and creamy sandalwood, it projects elegance and grandeur.', 7500, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (144, 101, 101, 101, 'Maahir Black Edition', 'The black stallion of smoke: dark birch tar smoke, heavy leather, sacred incense, and deep agarwood.', 'Maahir Black Edition is an uncompromising, intense smoky leather experience. Housed in a dark chrome equine sculpture, it features incense smoke, raw leather, and resinous amber for true aficionados of dark perfumery.', 7800, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (145, 101, 101, 101, 'Maahir Legacy', 'The silver stallion of crisp freshness: effervescent lime, iced spearmint, lavender, and mineral ambroxan.', 'Maahir Legacy (Silver Horse) is a pristine aromatic powerhouse reminiscent of niche luxury citrus scents. Opening with sparkling lime and cold mint, it settles into crisp juniper berries and breezy ambroxan.', 7600, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (146, 101, 101, 101, 'Najdia', 'The high-energy aquatic beast: fresh lemon, green apple, refreshing oceanic accord, and clean cedar.', 'Najdia is an invigorating sports aquatic fragrance designed for the modern active man. Crisp citrus and watery notes are fortified with cinnamon and aromatic lavender, ensuring unmatched hot-weather performance.', 5200, 90, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (147, 101, 101, 101, 'Hayaati', 'The crowd-pleasing daily driver: juicy red apple, warm cinnamon spice, sweet vanilla, and modern woods.', 'Hayaati represents effortless charm and casual luxury. Its playful combination of sweet apple and warm cinnamon over comforting vanilla makes it one of the most versatile signature scents available.', 5500, 80, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (148, 102, 101, 101, 'Hayaati Florence', 'Romantic Tuscan garden: sparkling pink grapefruit, exotic litchi, fresh peony blossoms, and soft musk.', 'Hayaati Florence evokes a springtime stroll through Italian flower markets. A delightful blend of sweet litchi and grapefruit leads into dewy peony and rose, finishing with a tender vanilla-musk touch.', 5800, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (149, 103, 101, 101, 'Hayaati Gold Elixir', 'Golden luxury nectar: juicy peach, sparkling bergamot, golden saffron threads, and soft leather.', 'Hayaati Gold Elixir enriches the Hayaati lineage with golden opulence. Peach and saffron provide a warm, radiant core complemented by smooth leather and amber.', 6000, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (150, 103, 101, 101, 'Ajwad', 'Mosaic flacon of sweet magic: candied mixed berries, romantic rose petals, Madagascar vanilla, and cedar.', 'Housed in a gorgeous wooden-inlay mosaic bottle, Ajwad is an intoxicating sweet-fruity perfume. Rich berries and rose mingle with creamy vanilla and cedar, offering tremendous projection.', 6200, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (151, 102, 101, 101, 'Ajwad Pink to Pink', 'The pink guava cocktail: exotic pink guava, lychee, magnolia petals, soft suede, and vanilla.', 'Ajwad Pink to Pink introduces an unexpected juxtaposition of tropical pink guava and delicate magnolia against sophisticated suede and ambergris, housed in an ornate pink mosaic flacon.', 6800, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (152, 103, 101, 101, 'Musk Mood', 'The essence of pure cleanliness: pristine white musk, gentle citrus, powdery florals, and sandalwood.', 'Musk Mood is the benchmark for clean, fresh-linen fragrances. Gentle, intimate, and comforting, it surrounds you in pure white musk and subtle vanilla, ideal after bathing or for daily prayer.', 5000, 70, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (153, 103, 101, 101, 'Pure Musk', 'Purity personified: ethereal white musk, velvet violets, sweet lilies, and soft powdery amber.', 'Pure Musk by Lattafa is an angelic, velvety fragrance that celebrates timeless white musk. Understated yet deeply memorable, it provides a clean, powdery aura that lasts throughout the day.', 4800, 65, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (154, 103, 101, 101, 'Opulent Red', 'Bold scarlet mystery: blood orange, boozy cognac, creamy tuberose, amber, and Madagascar vanilla.', 'Opulent Red is a daring, seductive creation. Combining the tartness of blood orange with rich aged cognac, heady tuberose, and amber, it creates an electric presence for memorable evening events.', 6500, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (155, 103, 101, 101, 'Opulent Oud', 'Rich dark velvet: spicy cinnamon bark, golden saffron, velvety red rose, and deep resins.', 'Opulent Oud offers a luxurious oriental journey. Enclosed in an engraved black and gold bottle, it unites saffron and cinnamon with dark agarwood and warm amber.', 6200, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (156, 101, 101, 101, 'Suqraat', 'Deep Mediterranean sea: crisp bergamot, fresh ginger root, violet leaf, and rich cypress.', 'Suqraat captures the mysterious depth of the Mediterranean sea. Opening with zesty bergamot and fiery ginger, it transitions into aquatic violet leaves and noble cypress for a truly distinguished masculine signature.', 6000, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (157, 103, 101, 101, 'Ana Abiyedh', 'The white velvet sensation: luscious sweet pear, airy white musk, cardamom, and golden saffron.', 'Ana Abiyedh (White) is an addictive, cloud-like fragrance reminiscent of iconic Italian fruity-musk perfumes. Crisp pear and bergamot dance with silky white musk and sweet vanilla.', 5600, 70, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (158, 103, 101, 101, 'Ana Abiyedh Rouge', 'The scarlet crystal aura: golden caramel, sweet nashi pear, mineral ambergris, and soft oakmoss.', 'Ana Abiyedh Rouge delivers the beloved airy, cotton-candy-meets-crystal-amber aura. With touches of crisp Asian pear and spun sugar over an ambergris base, it turns heads everywhere.', 5800, 65, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (159, 101, 101, 101, 'Ana Abiyedh Leather', 'Refined equestrian luxury: aromatic green cardamom, powdery orris root, and rich tan leather.', 'Ana Abiyedh Leather is a tailored, gentlemanly leather scent. Fresh spices and juniper berries accent a supple leather heart, yielding an aroma of bespoke saddles and luxury vehicle interiors.', 5800, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (160, 102, 101, 101, 'Mayar', 'Succulent exotic garden: juicy chilled lychees, tart raspberries, dewy white roses, and vanilla.', 'Mayar is an effervescent, joyful feminine perfume in a gorgeous rose-tinted bottle. Chilled lychee and raspberries lead the way into an enchanting heart of white rose and creamy vanilla.', 7000, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (161, 102, 101, 101, 'Mayar Natural Intense', 'Lush lagoon serenity: hydrating coconut water, green fig leaf, crisp melon, and aquatic lotus blossoms.', 'Mayar Natural Intense transports you to a tranquil rainforest oasis. Hydrating coconut water and crisp fig blend with water lilies and sheer woods for a uniquely refreshing experience.', 7500, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (162, 101, 101, 101, 'Ejaazi', 'Classic executive cologne: zesty orange, Mediterranean myrtle, warm cardamom, and rich ambroxan.', 'Ejaazi is a heavy-glass executive powerhouse. Clean, uplifting citrus and herbs meet rich cinnamon and patchouli, projecting confidence and dependability in business environments.', 5400, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (163, 101, 101, 101, 'Ejaazi Intensive Silver', 'Crisp ocean breeze: tart grapefruit, salty sea notes, aromatic cedar needles, and mineral ambergris.', 'Ejaazi Intensive Silver brings an invigorating aquatic profile to the collection. Cool sea breezes and tart grapefruit combine with marine ambergris for exceptional summer versatility.', 5600, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (164, 101, 101, 101, 'Kismet for Men', 'Gentlemen''s lounge: roasted coffee beans, dark cacao, spicy nutmeg, and rich patchouli.', 'Kismet for Men is tailored for evening sophistication. Featuring dark roasted coffee, bitter cacao, and earthy patchouli, it evokes the ambiance of an exclusive private club.', 6800, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (165, 103, 101, 101, 'Kismet Magic', 'The boozy cognac dream: aged French cognac, spicy cinnamon, oak barrel staves, and nutty praline.', 'Formerly celebrated under the name Kismet Angel, Kismet Magic is an intoxicating warm gourmand. Rich French cognac and cinnamon flow into buttery praline and oakwood.', 7500, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (166, 102, 101, 101, 'Haya', 'Celebration in a pink crystal bottle: sparkling champagne bubbles, wild strawberries, and vanilla orchid.', 'Haya is a sparkling celebration of life and joy. Effervescent champagne and ripe wild strawberries mingle with white gardenias and nutty praline, creating an unforgettable festive charm.', 7200, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (167, 103, 101, 101, 'Al Noble Safeer', 'The velvet deer bottle: bitter herbal artemisia, aromatic forest greens, patchouli, and nutty woods.', 'Al Noble Safeer, presented in an extraordinary green velvet bottle crowned with a golden stag head, is a masterclass in green aromatic perfumery. Sophisticated and dry, it stands out from ordinary scents.', 7200, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (168, 103, 101, 101, 'Al Noble Wazeer', 'The brown velvet stag: dark artisan chocolate, gooey caramel, sweet pear, and fresh cooling mint.', 'Al Noble Wazeer features a striking brown velvet bottle with a golden stag head. It surprises with rich dark chocolate, gooey caramel, and ripe pears contrasted by cooling mint leaves.', 7200, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (169, 103, 101, 101, 'Al Noble Ameer', 'The black velvet stag: crisp apple, spicy clove, fragrant rosemary, dark oud, and noble cypress.', 'Al Noble Ameer completes the velvet stag trilogy. A commanding blend of rosemary, crisp apple, spicy clove, and resinous agarwood, it radiates authority and distinction.', 7200, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (170, 103, 101, 101, 'Sutoor', 'The boozy peach fantasy: succulent ripe peach flesh, dark aged rum, French cognac, and patchouli.', 'Sutoor is a decadent peach-cognac delight. Inspired by bittersweet nectar, it pairs luscious peach and blood orange with aged rum and patchouli, creating a magnetic trail.', 7400, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (171, 103, 103, 102, 'Bright Peach', 'Niche peach seduction: intoxicating peach nectar, bitter blood orange, dark rum, and patchouli.', 'Bright Peach by Maison Alhambra is an artistic tour de force. Capturing the sweet, sensual aroma of ripe peach drenched in spiced rum and cognac, it is rich, bold, and delightfully provocative.', 6200, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (172, 103, 103, 102, 'Woody Oud', 'The pinnacle of private-blend elegance: precious rosewood, smoky agarwood, cardamom, and tonka.', 'Woody Oud by Maison Alhambra provides an accessible gateway to elite smoky-wood perfumery. Rare rosewood and cardamom meet rich agarwood and amber for an aristocratic signature.', 6400, 65, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (173, 103, 103, 102, 'Tobacco Touch', 'Opulent gentlemen''s study: rich cured tobacco leaves, vanilla bean, roasted tonka, and dried fruits.', 'Tobacco Touch is a warm, enveloping masterpiece. Reminiscent of a private library with leather armchairs, it wraps aromatic tobacco leaves and blossoms in creamy vanilla and tonka.', 6500, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (174, 103, 103, 102, 'Fabulo Intense', 'Bold, decadent luxury: bitter almond, powdery orris, supple black leather, and creamy tonka bean.', 'Fabulo Intense by Maison Alhambra is unabashedly glamorous. Bitter almond and Tuscan orris soften a core of luxurious leather, settling into cashmeran and tonka.', 6400, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (175, 103, 103, 102, 'Porto Neroli', 'Sunlit Italian Riviera: sparkling Tunisian neroli, chilled citrus groves, and white orange blossom.', 'Porto Neroli captures the sparkling azure waters and sun-drenched cliffs of the Italian coast. Tunisian neroli, Sicilian lemon, and orange flowers create the quintessential summer escape.', 6200, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (176, 102, 103, 102, 'Lovely ChÃ¨rie', 'Decadent cherry liqueur: dark black cherries, bitter almond, Turkish rose, and Peru balsam.', 'Lovely ChÃ¨rie is an intoxicating cherry-almond confectionery. Luscious ripe black cherries steeped in fine liqueur mingle with roasted tonka bean and warm spices.', 6400, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (177, 103, 103, 102, 'Rose Petals', 'Thorny, spicy rose garden: triple rose trilogy (May, Bulgarian, Turkish), fiery Sichuan pepper, and patchouli.', 'Rose Petals brings a sharp, modern edge to classic rose perfumery. Rare Sichuan pepper and golden turmeric pierce through three distinct rose varietals, supported by patchouli.', 6200, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (178, 101, 103, 102, 'Toscano Leather', 'Florentine leather workshop: sweet red raspberry, aromatic thyme, rich saffron, and black suede.', 'Toscano Leather is an authoritative leather creation. The unexpected pairing of tart sweet raspberry with dark, smoky leather and saffron results in an unforgettable masculine aroma.', 6500, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (179, 101, 103, 102, 'Salvo Intense', 'Wild desert twilight: sparkling Calabrian bergamot, tingling Sichuan pepper, and noble ambroxan.', 'Salvo Intense captures the raw majesty of desert twilight. Crisp, sparkling bergamot and spicy Sichuan pepper give way to noble ambroxan and cedar, offering tremendous longevity.', 5800, 70, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (180, 103, 103, 102, 'Baroque Rouge 540', 'The crimson crystal aura: golden saffron, Moroccan bitter almond, cedar, and mineral ambergris.', 'Baroque Rouge 540 by Maison Alhambra radiates the iconic, airy crystal-amber profile. Sparkling saffron and sweet almond meld into transparent ambergris for an unmistakably luxurious trail.', 6200, 75, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (181, 102, 103, 102, 'Delilah Pour Femme', 'The queen of pink roses: tart rhubarb, chilled lychee, dewy Turkish rose, peony, and cashmeran.', 'Delilah Pour Femme is celebrated worldwide for its stunningly faithful rendition of the iconic French luxury rose. Rhubarb and lychee introduce a radiant Turkish rose and cashmere heart in an elegant frosted pink flacon.', 6600, 65, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (182, 101, 103, 102, 'Jorge Di Profondo', 'Deep ocean dive: crystalline sea notes, green mandarin, aromatic rosemary, and mineral amber.', 'Jorge Di Profondo plunges into the exhilarating depths of the open sea. Marine notes and green mandarin awaken the senses, anchored by Mediterranean herbs and mineral patchouli.', 5800, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (183, 101, 103, 102, 'Jean Lowe Immortal', 'High-luxury masculine freshness: sparkling grapefruit, fresh spicy ginger root, and rich ambroxan.', 'Jean Lowe Immortal (celebrating the L''Immensite aesthetic) is an absolute masterpiece of crisp masculine elegance. Sparkling grapefruit and sharp ginger rest on amber and ambroxan, exuding pure prestige.', 7500, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (184, 103, 103, 102, 'Jean Lowe Nouveau', 'Nocturnal luxury: bittersweet cocoa, mystical incense, tart blackcurrant, rose, and dark oud.', 'Jean Lowe Nouveau combines rich raw cocoa and incense with precious oud and blackcurrant. An intriguing, dark unisex composition that commands attention.', 7800, 35, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (185, 103, 103, 102, 'Jean Lowe Ombre', 'Desert nomadic smoke: sweet tart raspberry, sacred incense tears, benzoin, and rich Assam oud.', 'Jean Lowe Ombre is a reverent exploration of Middle Eastern oud heritage. Combining succulent raspberry with smoky incense and agarwood, it delivers majestic longevity and sillage.', 7800, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (186, 101, 103, 102, 'Victorioso', 'The scent of victory: fresh grapefruit, oceanic salt spray, bay leaf, and guaiac wood.', 'Victorioso captures athletic prowess and masculine energy. A refreshing ocean accord and grapefruit open into bay leaf and woods, offering high impact throughout the day.', 5400, 70, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (187, 101, 103, 102, 'Victorioso Victory', 'Sweet evening victory: sharp pink pepper, calming lavender, resinous incense, and warm vanilla tonka.', 'Victorioso Victory takes the winning DNA into the night with sweet, smoky vanilla, calming lavender, and resinous frankincense.', 5600, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (188, 101, 103, 102, 'Glacier Pour Homme', 'Sailor''s charm: fresh spearmint, calming lavender, orange blossom, cinnamon, and bourbon vanilla.', 'Glacier Pour Homme is a timeless classic barbershop fougere. Uplifting mint and lavender are sweetened with cinnamon and vanilla, projecting effortless sex appeal.', 5500, 65, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (189, 101, 103, 102, 'Glacier Ultra', 'Party powerhouse: sweet juicy pear, iced mint, black vanilla husk, cinnamon, and amber.', 'Glacier Ultra is the ultimate nightlife weapon. Opening with delicious sweet pear and crisp mint, it unfolds into warm cinnamon and black vanilla for unbeatable club performance.', 5800, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (190, 101, 103, 102, 'Hercules', 'Warm heroic tobacco: spicy cinnamon bark, cured tobacco leaf, church incense, and woody vanilla.', 'Hercules by Maison Alhambra channels ancient heroic strength. Cinnamon and warm pepper introduce a commanding core of tobacco leaf and incense, finished with comforting vanilla and cedarwood.', 6200, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (191, 101, 103, 102, 'Cassius', 'Warm apple and saffron: crisp green apple, nutmeg, tonka bean, floral osmanthus, and patchouli.', 'Cassius blends crisp green apple and exotic saffron with tonka bean and patchouli, creating a dignified, sophisticated fragrance for refined occasions.', 6200, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (192, 101, 103, 102, 'Galatea', 'Noble leather steed: aromatic cypress, saffron, velvety rose, powdery orris, and saddle leather.', 'Galatea presents a royal equestrian harmony. Fresh herbs, saffron, and floral iris soften a core of noble leather and cedarwood.', 6200, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (193, 103, 103, 102, 'Philos Pura', 'Mediterranean fruit basket: sun-ripened oranges, lemons, sweet tropical fruits, vanilla, and white musk.', 'Philos Pura is an intoxicating, fruity-sweet fragrance celebrating Mediterranean sunshine. A vibrant basket of juicy citrus and fruits rests on creamy vanilla and clean musk.', 6000, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (194, 103, 103, 102, 'Philos Rosso', 'Scarlet velvet rose: intoxicating davana liqueur, dark patchouli, violet, and golden amber.', 'Philos Rosso is a romantic, velvety rose experience. Enveloping damask rose and herbal davana in dark patchouli and amber, it creates an aura of deep passion.', 6000, 45, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (195, 101, 103, 102, 'Versencia Oro', 'Mythic god of passion: crisp mint, tart green apple, tonka bean, ambergris, and sweet cedar.', 'Versencia Oro channels passionate masculine vitality. Crisp mint and green apple yield to warm tonka bean and vanilla, ensuring unmatched magnetic appeal.', 5400, 70, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (196, 102, 103, 102, 'Versencia Crystal', 'Crystalline water jewel: tart Japanese yuzu, pomegranate gems, frosted lotus, and sheer peony.', 'Versencia Crystal is sheer, luminous perfection. Sparkling yuzu and chilled pomegranate open into an ethereal heart of lotus and peony, drying into soft amber-musk.', 5400, 60, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (197, 102, 103, 102, 'B.A.D. Femme', 'Daring stilettos: roasted almond, dark espresso, white tuberose, cacao pod, and sweet praline.', 'B.A.D. Femme celebrates duality and confidence. Roasted almond and rich espresso contrast with luminous white tuberose and decadent cacao for an unforgettable evening presence.', 6000, 65, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (198, 101, 103, 102, 'Dark Door Intense', 'Aristocratic powdery iris: French lavender, velvety Tuscan iris, ambrette seeds, and clean cedar.', 'Dark Door Intense is the epitome of modern formal elegance. Powdery Tuscan iris and sweet pear rest upon noble Virginian cedar and vetiver, perfectly matching tailored black-tie attire.', 6500, 50, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (199, 102, 103, 102, 'Libbra', 'Freedom and power: French lavender, Moroccan orange blossom, sweet blackcurrant, and golden vanilla.', 'Libbra expresses radiant freedom. Combining French lavender typically found in masculine colognes with sensual Moroccan orange blossoms and rich Madagascar vanilla, it is fierce and captivating.', 6000, 55, 'Lattafa Official UAE', 'https://lattafa.com', 1),
    (200, 103, 103, 102, 'Sceptre Malachite', 'The emerald sceptre: tart green mandarin, tropical mango nectar, clary sage, and noble amber.', 'Sceptre Malachite is crowned with a stunning green gem flacon. It blends green mandarin, mango, and mineral amber into an aristocratic scent fit for royalty.', 7500, 40, 'Lattafa Official UAE', 'https://lattafa.com', 1)
